        console.error("Content-Type header is incorrect or missing:", pm.response.headers, err);
        throw err;
    }
});

pm.test("Response contains 'items' array with elements", function () {
    try {
        pm.expect(response).to.have.property("items").that.is.an("array").and.not.empty;
        console.log("'items' array is present and not empty.");
