// Si falta alguna propiedad obligatoria va a fallar

pm.test("Each bond has required properties", function () {

    if (response.items.length === 0) {
        throw new Error("'items' array is empty, cannot validate bond properties.");
    }

    response.items.forEach((bond, index) => {
        pm.expect(bond).to.include.keys("shortName", "name", "debtType", "links");
        pm.expect(bond.links).to.include.keys("coupons", "identifiers", "self", "issueConditions", "paymentSummary");
        console.log(`Bond ${index} validated successfully.`);
    });
});

// Si todas las propiedades existen pero sus valores están vacias o no tienen el formato esperado

pm.test("Each bond property has the correct format", function () {

    // Verificar si el array 'items' está vacío
    if (response.items.length === 0) {
        throw new Error("'items' array is empty, cannot validate bond properties.");
    }

    response.items.forEach((bond, index) => {
        // Validar bond.shortName
        pm.expect(bond).to.have.property("shortName").that.is.a("string");
        console.log(`Bond ${index}: shortName is valid: ${bond.shortName}`);

        // Validar bond.name
        pm.expect(bond).to.have.property("name").that.is.a("string");
        console.log(`Bond ${index}: name is valid: ${bond.name}`);

        // Validar bond.debtType
        pm.expect(bond).to.have.property("debtType").that.is.a("string");
        console.log(`Bond ${index}: debtType is valid: ${bond.debtType}`);

        // Validar bond.links
        pm.expect(bond).to.have.property("links").that.is.an("object");
        console.log(`Bond ${index}: links object is present.`);

        // Validar cada propiedad dentro de bond.links
        ["coupons", "identifiers", "self", "issueConditions", "paymentSummary"].forEach(linkKey => {
            pm.expect(bond.links).to.have.property(linkKey).that.is.a("string");
            pm.expect(bond.links[linkKey]).to.match(/^https?:\/\/[^\s$.?#].[^\s]*$/gm); // Comprobar URL válida
            console.log(`Bond ${index}: ${linkKey} link is valid: ${bond.links[linkKey]}`);
        });
    });
});

// Valida los links del bono

pm.test("Links are valid URLs", function () {
    try {

        // Verificar si el array 'items' está vacío
        pm.expect(response.items).to.not.be.empty; // Este test fallará si 'items' está vacío.

        response.items.forEach((bond, index) => {
            Object.entries(bond.links).forEach(([key, link]) => {
                pm.expect(link).to.match(/^https?:\/\/[^\s$.?#].[^\s]*$/gm);
                console.log(`Link '${key}' in bond ${index} is valid:`, link);
            });
        });
    } catch (err) {
        console.error("Error validating links:", err);
        console.log("Response body:", pm.response.text());
        throw err;
    }
});

