pm.test("Start parameter skips the correct number of bonds", function () {
    try {
        // Obtener parámetros `start` y `limit` de la solicitud
        const limit = parseInt(pm.request.url.query.get("limit")) || 10; // Default 10 si no se proporciona
        const start = parseInt(pm.request.url.query.get("start")) || 1; // Default 1 si no se proporciona

        // Validar que la respuesta contiene 'items' como un array
        pm.expect(response).to.have.property("items").that.is.an("array");

        // Validar que el primer elemento de 'items' corresponde al índice `start`
        if (response.items.length > 0) {
            // Extraer el valor de `start` desde el vínculo `self`
            const selfLink = response.links.self;
            const selfStartMatch = selfLink.match(/start=(\d+)/);
            const selfStart = selfStartMatch ? parseInt(selfStartMatch[1]) : 1;

            pm.expect(selfStart).to.equal(start);

            console.log(
                `Validated that the first bond in response starts at index ${start}.`
            );
        } else {
            console.log("No bonds returned in the response, validation skipped.");
        }
    } catch (err) {
        console.error("Error validating start parameter:", err);
        console.log("Response body:", pm.response.text());
        throw err;
    }
});

pm.test("Error 406 response structure", function () {

    if (pm.response.code === 406) {
        pm.expect(response).to.have.property("code", 406);
        pm.expect(response).to.have.property("message", "Cannot generate a response entity with acceptable characteristics.");
        pm.expect(response).to.have.property("allowedMediaTypes").that.is.an("array").and.includes("application/vnd.mercap.valid.entity.example+json;version=1.0.0");
        pm.expect(response).to.have.property("allowedLanguageTags").that.is.an("array").and.includes("en-US");

        console.log("406 error response is valid with expected structure.");
    } else {
        console.log("Response code is not 406, no validation necessary.");
    }
});

pm.test("Limit parameter is 0, response should be 400", function () {
    try {
        // Obtener el valor del parámetro 'limit' de la URL de la solicitud
        const limit = parseInt(pm.request.url.query.get("limit"));

        // Verificar si el valor de 'limit' es 0
        if (limit === 0) {
            // Validar que el código de respuesta sea 400
            pm.response.to.have.status(400);

            // Validar que el cuerpo de la respuesta contenga el mensaje esperado
