            pm.expect(response.message).to.eql("The page limit must be positive");

            console.log("Correct error response for 'limit' = 0.");
        } else {
            console.log("Limit is not 0, skipping error validation.");
        }
    } catch (err) {
        console.error("Error validating limit parameter 0:", err);
        console.log("Response body:", pm.response.text());
        throw err;
    }
});

