const VALID_UNIT_TYPES = [
    "paid-in-issue-currency",
    "issued-in-indexed-unit",
    "payment-currency-differs-from-issue-currency"
];
const VALID_FX_SIDES = ["bid", "ask", "mid"];

pm.test("cashflowUnits: estructura válida por variante", function () {
    response.items.forEach((bond, i) => {
        const cu = bond.issue.cashflowUnits;
        pm.expect(cu, `bond ${i} sin cashflowUnits`).to.be.an("object");
        pm.expect(VALID_UNIT_TYPES, `bond ${i} type inválido: ${cu.type}`).to.include(cu.type);
        pm.expect(cu).to.have.property("issueCurrency").that.is.a("string");

        if (cu.type === "payment-currency-differs-from-issue-currency") {
            pm.expect(cu).to.have.property("paymentCurrency").that.is.a("string");

            // Campos viejos NO deben venir más (regresión del cambio)
            pm.expect(cu).to.not.have.property("exchangeMarket");
            pm.expect(cu).to.not.have.property("exchangeSource");

            // Nuevo filtro con al menos un criterio
            const f = cu.exchangeRateFilter;
            pm.expect(f, `bond ${i} sin exchangeRateFilter`).to.be.an("object");
            const criterios = ["source", "contributor", "currencyPairAsKnownBySource", "type"]
                .filter(k => f[k] !== undefined && f[k] !== null && f[k] !== "");
            pm.expect(criterios.length, `bond ${i}: filtro sin criterios`).to.be.at.least(1);

            if (f.type !== undefined) {
                pm.expect(VALID_FX_SIDES, `bond ${i} type de FX inválido: ${f.type}`).to.include(f.type);
            }

            pm.expect(cu).to.have.property("exchangeDateOffsetDays").that.is.a("number");
            pm.expect(cu).to.have.property("exchangeCalendar").that.is.a("string");
        }
    });
});

