pm.test("validar que solo devuelva items asociados al issuer enviado por parametro", function (done) {

    const Request = {
        url: issuer,
        method: 'GET',
        header: { 'Authorization': "Bearer " + pm.environment.get("AUTHENTICATION_BEARER") }
    };

    pm.sendRequest(Request, function (err, res) {

        if (err) {
            console.error(err); // ← fix: era "error"
            done(err);
            return;
        }

        const issuerName = res.json().name;
        let pending = response.items.length;

        if (pending === 0) {
            done();
            return;
        }

        response.items.forEach((bond) => {
            const rq = {
                url: bond.links.issueConditions,
                method: 'GET',
                header: { 'Authorization': "Bearer " + pm.environment.get("AUTHENTICATION_BEARER") }
            };

            pm.sendRequest(rq, function (err, resp) {

                if (err) {
                    console.error(err);
                    done(err);
                    return;
                }

                pm.expect(resp.json().issuer).to.equal(issuerName);

                pending--;
                if (pending === 0) {
                    done(); // ← notifica que todos los requests async terminaron
                }
            });
        });
    });
});

let rq = {
    url: pm.environment.get("PEPPER_LOCATION") + "/instrument-issuers",
    method: 'GET',
    header: {'Authorization': "Bearer " + pm.environment.get("AUTHENTICATION_BEARER"),}
};

pm.sendRequest(rq, function (err, resp) {

    if (err) {
        console.error(err);
        return;
    }

    const items = (resp.json() || {}).items || [];

    if (items.length === 0) {
        console.error("/instrument-issuers no devolvio issuers: no se puede setear la variable 'issuer'.");
        return;
