function req(url, method, accept, callback) {
    pm.sendRequest({
        url: url,
        method: method,
        header: {
            'Accept': accept,
            'Authorization': `Bearer ${pm.environment.get("AUTHENTICATION_BEARER")}`
        }
    }, (err, res) => {
        if (err) {
            console.error("Error en request a " + url, err);
            return;
        }
        callback(res);
    });
}

