    if (etag) pm.environment.set("Etag", etag);

    req(pepperCore + "/debt-types", 'GET', 'application/vnd.mercap.debt-type+json;version=1', (res) => {
        pm.environment.set("debtType", res.json()?.items?.[0]?.links?.self);

