  if (typeof response.issue.issueCountry !== "string") erroresFormato.push("issueCountry debe ser string (URI)");
  if (typeof response.issue.issuer !== "string") erroresFormato.push("issuer debe ser string (URI)");
  if (typeof response.issue.law !== "string") erroresFormato.push("law debe ser string (URI)");

  if (typeof response.issue.faceValueAmount !== "number") erroresFormato.push("faceValueAmount debe ser number");

  if (!Number.isInteger(response.couponPayment.offsetDays)) erroresFormato.push("offsetDays debe ser integer");
  if (response.couponPayment.movementPolicy !== "next-working-day") erroresFormato.push("movementPolicy debe ser 'next-working-day'");
  if (typeof response.couponPayment.calendar !== "string") erroresFormato.push("calendar debe ser string (URI)");
  if (typeof response.couponPayment.keepInMonth !== "boolean") erroresFormato.push("keepInMonth debe ser boolean");

  if (erroresFormato.length > 0) {
    throw new Error(`Errores de formato/tipo: ${erroresFormato.join(", ")}`);
  }
});

pm.test("Debe existir objeto links con atributos self y deactivate", function () {
    pm.expect(response.links).to.have.property("self");
    pm.expect(response.links).to.have.property("deactivate");
});

pm.test("El atributo shortName debe ser '0AJWR6'", function () {
    pm.expect(response.shortName).to.eql("0AJWR6");
});

pm.test("El atributo name debe ser 'CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)'", function () {
    pm.expect(response.name).to.eql("CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)");
});

pm.test("El atributo issueDate debe ser " + date, function () {
    pm.expect(response.issue.issueDate).to.eql(date);
});

pm.test("El atributo maturityDate debe ser " + futureDate, function () {
    pm.expect(response.maturityDate).to.eql(futureDate);
});

pm.test("El atributo dayCountBasis.type debe ser 'business-day-252'", function () {
