});

const date = new Date().toLocaleDateString('sv');
pm.environment.set("date", date);

const futureDate =  new Date(date);
futureDate.setFullYear(futureDate.getFullYear() + 1);


const firstCouponPayment = new Date(date);
firstCouponPayment.setMonth(firstCouponPayment.getMonth() + 3);
pm.environment.set("firstCouponPayment", firstCouponPayment.toLocaleDateString('sv'));

pm.environment.set("shortName", "0AJWR6");
pm.environment.set("name", "CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)");

const calendar = pm.environment.get("holidays-location")

//logica para evitar dias no habiles

const queryRequest = {
    url: calendar + "/move-forward",
    method: 'QUERY',
    header: {
            'Accept': 'application/vnd.mercap.date-movement-result+json;version=1',
            'Content-Type': 'application/vnd.mercap.date-movement+json;version=1.0.0',
            'Authorization': 'Bearer ' + pm.environment.get("AUTHENTICATION_BEARER"),
    },
    body: JSON.stringify({
        "duration": "P1D",
        "startingDates": [
            futureDate.toLocaleDateString('sv')
        ]
    })
};

pm.sendRequest(queryRequest, (error, queryRequest) => {
    if (error) {
        console.error(error);
        return;
    }

    pm.environment.set("futureDate", queryRequest.json()[0].endDate);

});

