    // ============================================================
    // Helpers reutilizables — disponibles en todos los test scripts via:
    //   eval(pm.globals.get("__helpers__"));
    // ============================================================
    pm.globals.set("__helpers__", `
    var H = {};

    /**
     * Calcula los días hábiles entre dos fechas (excluyendo feriados y fines de semana).
     * @param {string} startDate - Fecha inicio en formato YYYY-MM-DD
     * @param {string} endDate - Fecha fin en formato YYYY-MM-DD
     * @param {Array} holidayRules - Array de reglas de feriados del calendario
     * @returns {number} - Cantidad de días hábiles
     */
    H.calcularDiasHabiles = function(startDate, endDate, holidayRules) {
        // --- Parsear las reglas de feriados ---
        const isHoliday = H.buildHolidayChecker(holidayRules);

        let count = 0;
        const current = H.parseDate(startDate);
        const end = H.parseDate(endDate);

        while (current <= end) {
            if (!isHoliday(current)) {
            count++;
            }
            current.setDate(current.getDate() + 1);
        }

        return count;
    }

    /**
     * Construye una función que determina si una fecha dada es feriado,
     * según las reglas del calendario.
     */
    H.buildHolidayChecker =function(holidayRules) {
        const fixedDates = new Set();       // type: "date"        → "YYYY-MM-DD"
        const fixedMonthDays = new Set();   // type: "day-of-month" → "MM-DD"
        const blockedWeekdays = new Set();  // type: "day-of-week"  → 0 (Sun) … 6 (Sat)

        const DAY_MAP = {
            Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3,
            Thursday: 4, Friday: 5, Saturday: 6,
        };

        for (const rule of holidayRules) {
            const def = rule.definition;

            if (def.type === "date") {
            fixedDates.add(def.date); // "YYYY-MM-DD"

            } else if (def.type === "day-of-month") {
            fixedMonthDays.add(def.dayOfMonth); // "MM-DD"

            } else if (def.type === "day-of-week") {
            blockedWeekdays.add(DAY_MAP[def.dayOfWeek]);
            }
        }

        return function isHoliday(date) {
            // 1. Día de la semana (ej: sábado/domingo)
            if (blockedWeekdays.has(date.getDay())) return true;

            const yyyy = date.getFullYear();
            const mm   = String(date.getMonth() + 1).padStart(2, "0");
            const dd   = String(date.getDate()).padStart(2, "0");

            // 2. Fecha exacta (ej: "2024-02-12")
            if (fixedDates.has( yyyy + "-" + mm + "-" + dd)) return true;

            // 3. Día/mes fijo todos los años (ej: "01-01" → 1° de enero)
            if (fixedMonthDays.has(mm + "-" + dd)) return true;

            return false;
        };
    }

    /** Parsea "YYYY-MM-DD" como fecha local (sin desfase de timezone). */
    H.parseDate = function(str) {
        const [y, m, d] = str.split("-").map(Number);
        return new Date(y, m - 1, d);
    }

    /**
     * Calcula una fecha a partir de una fecha base aplicando un offset de años, meses y/o días,
     * y la retorna formateada según el formato indicado.
     *
     * @param {Object} opciones
     * @param {Date}   [opciones.base]               - Fecha base. Si no se indica, se usa la fecha actual (now).
     * @param {number} [opciones.años=0]             - Años a sumar (negativo para restar)
     * @param {number} [opciones.meses=0]            - Meses a sumar (negativo para restar)
     * @param {number} [opciones.dias=0]             - Días a sumar (negativo para restar)
     * @param {string} [opciones.formato="DD/MM/YYYY"] - Formato de salida. Valores aceptados:
     *                                                   "YYYY-MM-DD", "YYYY/MM/DD",
     *                                                   "DD-MM-YYYY", "DD/MM/YYYY",
     *                                                   "DD-MM-YY",   "DD/MM/YY"
     * @returns {string} Fecha calculada en el formato solicitado.
     * @throws  {Error}  Si el valor de base no es un objeto Date válido.
     * @throws  {Error}  Si el formato indicado no está entre los valores aceptados.
     */
    H.fechaOffset = function(opciones) {
        opciones = opciones || {};
        var anios   = opciones.anios  || 0;
        var meses   = opciones.meses  || 0;
        var dias    = opciones.dias   || 0;
        var formato = opciones.formato || "DD/MM/YYYY";

        var fecha;
        if (opciones.base !== undefined) {
            if (!(opciones.base instanceof Date) || isNaN(opciones.base.getTime())) {
                throw new Error("El parametro base debe ser un objeto Date valido.");
            }
            fecha = new Date(opciones.base.getTime());
        } else {
            fecha = new Date();
        }

        fecha.setFullYear(fecha.getFullYear() + anios);
        fecha.setMonth(fecha.getMonth() + meses);
        fecha.setDate(fecha.getDate() + dias);

        var dd   = ("0" + fecha.getDate()).slice(-2);
        var mm   = ("0" + (fecha.getMonth() + 1)).slice(-2);
        var yyyy = String(fecha.getFullYear());
        var yy   = yyyy.slice(-2);

        var formatos = {
            "YYYY-MM-DD": yyyy + "-" + mm + "-" + dd,
            "YYYY/MM/DD": yyyy + "/" + mm + "/" + dd,
            "DD-MM-YYYY": dd   + "-" + mm + "-" + yyyy,
            "DD/MM/YYYY": dd   + "/" + mm + "/" + yyyy,
            "DD-MM-YY":   dd   + "-" + mm + "-" + yy,
            "DD/MM/YY":   dd   + "/" + mm + "/" + yy
        };

        if (!formatos[formato]) {
            throw new Error("Formato no soportado: " + formato + ". Usar: " + Object.keys(formatos).join(", "));
        }

        return formatos[formato];
    };
    `);

    // ✅ Marcar como ejecutado
    pm.variables.set("folderSetupDone", "true");
}
